macro_rules! deps {
    () => {
        TempPath!();
    };
}

macro_rules! NamedTempFile {
    () => {
        deps!();
        # [doc = " A named temporary file."] # [doc = ""] # [doc = " The default constructor, [`NamedTempFile::new()`], creates files in"] # [doc = " the location returned by [`env::temp_dir()`], but `NamedTempFile`"] # [doc = " can be configured to manage a temporary file in any location"] # [doc = " by constructing with [`NamedTempFile::new_in()`]."] # [doc = ""] # [doc = " # Security"] # [doc = ""] # [doc = " Most operating systems employ temporary file cleaners to delete old"] # [doc = " temporary files. Unfortunately these temporary file cleaners don't always"] # [doc = " reliably _detect_ whether the temporary file is still being used."] # [doc = ""] # [doc = " Specifically, the following sequence of events can happen:"] # [doc = ""] # [doc = " 1. A user creates a temporary file with `NamedTempFile::new()`."] # [doc = " 2. Time passes."] # [doc = " 3. The temporary file cleaner deletes (unlinks) the temporary file from the"] # [doc = "    filesystem."] # [doc = " 4. Some other program creates a new file to replace this deleted temporary"] # [doc = "    file."] # [doc = " 5. The user tries to re-open the temporary file (in the same program or in a"] # [doc = "    different program) by path. Unfortunately, they'll end up opening the"] # [doc = "    file created by the other program, not the original file."] # [doc = ""] # [doc = " ## Operating System Specific Concerns"] # [doc = ""] # [doc = " The behavior of temporary files and temporary file cleaners differ by"] # [doc = " operating system."] # [doc = ""] # [doc = " ### Windows"] # [doc = ""] # [doc = " On Windows, temporary files are, by default, created in per-user temporary"] # [doc = " file directories so only an application running as the same user would be"] # [doc = " able to interfere (which they could do anyways). However, an application"] # [doc = " running as the same user can still _accidentally_ re-create deleted"] # [doc = " temporary files if the number of random bytes in the temporary file name is"] # [doc = " too small."] # [doc = ""] # [doc = " ### MacOS"] # [doc = ""] # [doc = " Like on Windows, temporary files are created in per-user temporary file"] # [doc = " directories by default so calling `NamedTempFile::new()` should be"] # [doc = " relatively safe."] # [doc = ""] # [doc = " ### Linux"] # [doc = ""] # [doc = " Unfortunately, most _Linux_ distributions don't create per-user temporary"] # [doc = " file directories. Worse, systemd's tmpfiles daemon (a common temporary file"] # [doc = " cleaner) will happily remove open temporary files if they haven't been"] # [doc = " modified within the last 10 days."] # [doc = ""] # [doc = " # Resource Leaking"] # [doc = ""] # [doc = " If the program exits before the `NamedTempFile` destructor is"] # [doc = " run, the temporary file will not be deleted. This can happen"] # [doc = " if the process exits using [`std::process::exit()`], a segfault occurs,"] # [doc = " receiving an interrupt signal like `SIGINT` that is not handled, or by using"] # [doc = " a statically declared `NamedTempFile` instance (like with [`lazy_static`])."] # [doc = ""] # [doc = " Use the [`tempfile()`] function unless you need a named file path."] # [doc = ""] # [doc = " [`tempfile()`]: fn.tempfile.html"] # [doc = " [`NamedTempFile::new()`]: #method.new"] # [doc = " [`NamedTempFile::new_in()`]: #method.new_in"] # [doc = " [`std::process::exit()`]: http://doc.rust-lang.org/std/process/fn.exit.html"] # [doc = " [`lazy_static`]: https://github.com/rust-lang-nursery/lazy-static.rs/issues/62"] pub struct NamedTempFile < F = File > { path : TempPath , file : F , }
    };
}

NamedTempFile!()